-- PropBetEdge — Women's Basketball History
-- Wikidata CC0 WNBA identity spine v1. No Wikipedia prose, ESPN data, WNBA payloads, or restricted provider pages.
begin;

do $seed$
declare
  v_doc uuid;
  v_run uuid;
  v_existing integer;
begin
  perform public.wbh_assert_ingestible('wikidata');
  select count(*) into v_existing from public.wbh_ingestion_runs where scope->>'dataset'='wikidata_wnba_identity_v1' and status='ok';
  if v_existing > 0 then
    if (select count(*) from public.wbh_persons) >= 1314 and (select count(*) from public.wbh_entity_source_ids where entity_type='person' and source_id='wikidata' and id_space='wikidata:P3588' and status='linked') >= 1314 then return; end if;
    raise exception 'wbh: Wikidata identity spine run exists but canonical counts are incomplete; refusing to guess' using errcode='P0001';
  end if;
  if exists (select 1 from public.wbh_persons) then raise exception 'wbh: persons already exist before first identity-spine load; refusing to merge implicitly' using errcode='P0001'; end if;
  values ('wikidata','wikidata:P3588:wnba_identity_snapshot_v1','https://query.wikidata.org/sparql + https://www.wikidata.org/w/api.php','GET','2026-09-16T10:29:34Z',200,'2f00c0ed3b7aab4f10a3b61182486a1488b02506963692718957deb6a470bc86','application/json',64342570,'hash_only','wbh_wikidata_identity_v1','Exact raw response bytes were length-framed, hashed, and not retained; normalized CC0 claims are committed in the manifest.') returning document_id into v_doc;
  values ('wikidata','wikidata_p3588_snapshot','1.0.0','wbh_wikidata_identity_v1','ingest','2026-09-16T10:29:34Z',jsonb_build_object('dataset','wikidata_wnba_identity_v1','people',1314,'raw_capture_sha256','2f00c0ed3b7aab4f10a3b61182486a1488b02506963692718957deb6a470bc86')) returning run_id into v_run;




























  update public.wbh_ingestion_runs set status='ok', counts=jsonb_build_object('persons',1314,'aliases',2046,'linked_source_ids',2628,'dob_day',1308,'dob_partial',0,'dob_absent',6,'sport_country_iso3',809) where run_id=v_run;
end $seed$;

commit;
